import net.neoforged.neoforge.registries.RegisterEvent;
import net.neoforged.neoforge.registries.RegistryBuilder;
import net.neoforged.neoforge.registries.NewRegistryEvent;

// Register to existing registry
NeoForge.EVENT_BUS.addListener((RegisterEvent event) -> {
    event.register(MyRegistryKeys.MY_CUSTOM_OBJECT, "my_object", () -> new MyCustomObject());
});

// Create custom registry
NeoForge.EVENT_BUS.addListener((NewRegistryEvent event) -> {
    event.create(new RegistryBuilder<>()
        .setName(new ResourceLocation(MODID, "my_registry"))
        .setType(MyCustomObject.class)
        .disableSync()
    );
});
